//
// Phase 1 (free reasoning, up to ~70% of budget): Emit unconstrained tokens so
//   the model can work through multi-step arithmetic before committing to a
//   structured answer. The prefixBudget is capped at maxSteps - 2, reserving at
//   least one step for OpenConstrainedSpan and at least one for
//   CloseSpanWithinBudget. Phase 1 is skipped when already inside a span.
//
// Phase 2 (constrained answer): Open one constrained span (appending "<<") and
//   fill it with a parser-valid arithmetic expression, then close it (appending
//   ">>") within the remaining budget via CloseSpanWithinBudget.
//
// The guidance instructs the model to write "<<int(expr)>>" exactly once at the
//   end, suppressing LaTeX and other forbidden syntax.
//
// Base case (maxSteps == 0): return immediately with cost = 0; the first
//   disjunct of the progress postcondition is satisfied.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Free-reasoning loop branch: the loop invariant explicitly asserts
//   !insideConstrainedOut and currentConstrainedOut == [], so the implication
//   is vacuously true on every iteration.
//
//   OpenConstrainedSpan branch: the helper sets currentConstrainedOut := [] and
//   insideConstrainedOut := true; parser.IsValidPrefix([]) holds by the method
//   precondition `requires parser.IsValidPrefix([])`, so the invariant is
//   established immediately after the call.
//
//   CloseSpanWithinBudget branch: the helper's postcondition guarantees
//   `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`,
//   so the invariant is re-established unconditionally after the call.
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   Free-reasoning loop: each iteration increments steps by exactly 1. When
//   next != eosToken, generated grows by exactly 1 token; when next == eosToken,
//   generated is unchanged but steps still increments by 1. In both sub-cases
//   the new |generated| <= |generatedPrefix| + new steps.
//
//   OpenConstrainedSpan: appends exactly the one "<<" delimiter token to
//   generated and increments steps by 1, so |generated| grows by 1 and steps
//   grows by 1, preserving the bound.
//
//   CloseSpanWithinBudget: its postcondition guarantees
//   |generatedOut| <= |generated_before| + closeBudget, and we set
//   steps := maxSteps = steps_before + closeBudget, so
//   |generatedOut| <= |generatedPrefix| + steps_before + closeBudget
//             == |generatedPrefix| + maxSteps.
// CSD_PROOF_SKETCH_END

// Phase 0: initialize all output parameters.
generated             := generatedPrefix;
insideConstrainedOut  := insideConstrained;
currentConstrainedOut := currentConstrained;
cost                  := 0;

if maxSteps == 0 {
  // Base case: maxSteps == 0 satisfies the first disjunct of the final postcondition.
  // cost = 0 = maxSteps satisfies cost <= maxSteps.
} else {
  helpers.AppendTaskGuidance(lm,
    "Solve step by step. At the very end, write the final answer ONCE as " +
    "<<int(expression)>> using only: bare variable names (no braces), integers, " +
    "+, -, *, /, //, %, (, ), int(). Example: <<int(n * price + base)>>. " +
    "No LaTeX, no {}, no **. Only ONE <<>> at the very end of your answer.");

  var steps: nat := 0;

  // Compute prefix budget: ~70 % of maxSteps, capped so at least 2 steps remain
  // for OpenConstrainedSpan and CloseSpanWithinBudget.
  var prefixBudget: nat;
  if maxSteps <= 2 {
    prefixBudget := 0;
  } else {
    prefixBudget := (maxSteps * 70) / 100;
    if prefixBudget > maxSteps - 2 {
      prefixBudget := maxSteps - 2;
    }
  }

  // Phase 1: unconstrained free-text reasoning chain.
  // Skipped when already inside a constrained span.
  if !insideConstrainedOut {
    while steps < prefixBudget
      invariant steps <= prefixBudget
      invariant prefixBudget <= maxSteps - 2 || maxSteps <= 2
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant |generated| <= |generatedPrefix| + steps
      decreases prefixBudget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Force-open exactly one constrained span.  The budget ensures steps < maxSteps here
    // whenever maxSteps > 0, so the guard is always entered on the normal exit path.
    if steps < maxSteps {
      var go, io, co := helpers.OpenConstrainedSpan(lm, generated);
      generated             := go;
      insideConstrainedOut  := io;
      currentConstrainedOut := co;
      steps                 := steps + 1;
    }
  }

  // Phase 2: complete and close the open constrained span within remaining budget.
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget: nat := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated             := cg;
    insideConstrainedOut  := ci;
    currentConstrainedOut := cc;
    steps                 := maxSteps;
  }

  cost := steps;
}
